WFJ.Data.add("gossip", {
  ["3e044d25778cb87d"] = { "Impari in fretta, tu, e sei pure <un/una> <bravo/brava> fabbro. Firmerei il tuo lavoro qualsiasi giorno della settimana. Ma sento che hai ancora qualcosa da imparare. Va' a parlare con Bengus Deepforge: è un maestro esigente, ma è anche uno dei migliori.", "." },
  ["3e05589572d79ac3"] = { "Salute, <piccolo/piccola>. Hai affari con i Seguaci di Idraxis?", "." },
  ["3e19e0b1c27f9ce0"] = { "Uno stregone, eh... Be', se hai in mente di fare quel genere di cose da queste parti, allora faresti meglio a tenere i tuoi demoni al guinzaglio, <ragazzo/ragazza>. Non mi piacciono i demoni, ma adoro piantarci dentro l'ascia. Mi capisci?\n\nOra lasciami in pace e va' a perderti nella Caverna degli Inganni. È lì che troverai quello stregone, Thistleheart.", "." },
  ["3e1b8dfde2985ee6"] = { "È l'ora della mia meditazione, lasciami.", "." },
  ["3e1c941d66057d41"] = { "Nessuno gnomo verrà lasciato indietro.", "." },
  ["3e1cc66c78145e50"] = { "Non un passo di più, ogre!", "." },
  ["3e1ecf54f58fceca"] = { "%s comincia a divorare avidamente il cibo.", "." },
  ["3e23ea846a1cf304"] = { "Frazier va giù! Frazier va giù! Va giù... eh? Quello non era Frazier?", "." },
  ["3e2447c6a59ecf5d"] = { "Mi sembri un po' scoss<o/a>, {name}. Stai bene?", "." },
  ["3e31dd865019293e"] = { "Sempre utile da avere, la Sopravvivenza è.\n\nKaerbrus è chi stai cercando. Di solito si trova vicino al pozzo lunare nel Parco.", "." },
  ["3e37eb67547e05a8"] = { "Bene, Razziatori! Sono arrivati gli ordini! Alla battaglia!", "." },
  ["3e4adbab8b38adc0"] = { "Deludente.", "." },
  ["3e5197d48dc6d9c3"] = { "Hai dimenticato la tua tenuta scolastica? Pensi che la moda sia più importante del dominio del Flagello?", "." },
  ["3e5f7fb395f26f17"] = { "Vattene! Io tengo consiglio con i signori del terrore, e le questioni di cui discutiamo non ti riguardano!", "." },
  ["3e626e5d37be14ce"] = { "Fa così male... Itharius, mio vecchio amico... ti prego, aiutami...", "." },
  ["3e67fb231b00d003"] = { "Leggo nei tuoi occhi che la tragedia di Stratholme non ti è estranea. Se desideri porre fine all'esistenza miserabile delle povere anime intrappolate laggiù, entra nel cerchio. Porta direttamente ai cancelli della città in fiamme.", "." },
  ["3e692c40473b582b"] = { "Ti senti uno chef? Va' a ⟦Undercity=Sepulcra⟧, a sud della città, per il tuo addestramento. Puoi prendere gli ascensori che scendono in fondo alle ⟦Ruins of Lordaeron=Rovine di Lordaeron⟧. Una volta arrivat<o/a>, parla con uno di quei goffi Guardiani di ⟦Undercity=Sepulcra⟧ per altre indicazioni.", "." },
  ["3e6ad2144be79bdd"] = { "Non ne ho mai visto uno così grande! Non vedo l'ora di spedirlo indietro per le ricerche...", "." },
  ["3e705f0dc45fbe0d"] = { "Vanndar Stormpike è il generale dell'esercito dell'⟦Alliance=Alleanza⟧ ad Alterac, e guida le sue forze da Dun Baldar.\n\nSe verrà sconfitto, l'⟦Alliance=Alleanza⟧ perderà di sicuro la battaglia per Alterac.", "." },
  ["3e720523c7c5c7c7"] = { "Per poco non mandavano a questo raduno mio fratello Loksey. Non sa nemmeno badare ai suoi segugi, figuriamoci rappresentare la ⟦Scarlet Crusade=Crociata Scarlatta⟧ in modo competente.", "." },
  ["3e7617a5b8e966bd"] = { "Salute, {class}. Sono il feldmaresciallo Snowfall, al comando dello sforzo bellico qui. Abbiamo una strada dura davanti, <ragazzo/ragazza>, quindi se puoi dare una mano, fallo. E non esitare a fare domande.", "." },
  ["3e8336be2b4bb5da"] = { "Grazie per le provviste, {name}.", "." },
  ["3e88cdfc96b2af4e"] = { "Risposta sbagliata, {name}. Vattene.", "." },
  ["3e9734dcbaa225a0"] = { "E se posso aggiungere, quel vestito è delizioso! Devi dirmi dove l'hai preso.", "." },
  ["3e9bdfa5d48f1a2c"] = { "Ammirate! Il Blue Recluse dà un banchetto in suo onore!", "." },
  ["3ea68482eb60a8d7"] = { "Schiacciateli tutti!", "." },
  ["3eaea0484ec64f5c"] = { "Dovremo cancellare i Maraudon dalla nostra lista. È troppo difficile lavorarci insieme...", "." },
  ["3eb20e8ec06e3922"] = { "Fun... funziona!", "." },
  ["3eb2dbb1d378fd80"] = { "E poi?", "." },
  ["3eb533b13f93cd8e"] = { "La mappa che hai in mano sembra mostrare una complessa rete di gallerie e strade sotterranee che convergono tutte in un punto sotto ⟦Ironforge=Forgiardente⟧.\r\n\nNon puoi sapere con certezza cosa dicano le rune, scritte nella brutta lingua runica e frastagliata dei nani ⟦Dark Iron=Ferroscuro⟧, ma puoi intuire lo scopo di quelle gallerie. Mentre leggi la mappa, una folata di vento ti investe e senti appena una voce nanica portata dal vento, che ti esorta a cercare un veggente della terra di nome \"Farsen\".", "." },
  ["3eb6417d68d49783"] = { "Confisco il mais che ha rubato, lo avverto che rubare è una strada che porta alla rovina e alla distruzione, ma lo lascio tornare dalla sua famiglia.", "." },
  ["3eb94d9b21360ca8"] = { "%s sviene e cade a terra.", "." },
  ["3eba342efbe64bc0"] = { "Va' alla Hunter's Hall nella ⟦Valley of Honor=Valle dell'Onore⟧, a ovest del Colosseo. Lì parla con Ormak Grimshot.", "." },
  ["3ec520e23dab50d8"] = { "Sono felice che tu l'abbia chiesto!\n\nLe professioni sono abilità legate alla creazione, alla raccolta e alla sopravvivenza in generale. Ce ne sono molte tra cui scegliere, e ognuna offre vantaggi e opportunità economiche tutte sue. Che tu cerchi ricchezza, l'occasione di rifornire il magazzino della tua gilda di oggetti utili, o semplicemente la soddisfazione di indossare un equipaggiamento fatto con le tue mani, c'è una professione che fa per te.\n\nLe ricette di creazione si possono imparare dagli istruttori, come quelli qui intorno, e da numerose altre fonti in tutta Azeroth. Una volta imparata una ricetta, puoi creare quell'oggetto quante volte vuoi, purché tu riesca a procurarti i materiali necessari.", "." },
  ["3ecf232021168e60"] = { "È stato proprio un bel combattimento. Riprendiamo fiato per un po'.", "." },
  ["3ecf795225819b1a"] = { "Lo rivoglio, mortale. Atiesh... Da esso creerei di nuovo gli ⟦Highborne=Alti Nobili⟧. Rivorrei tutto. Perfino la Regina...", "." },
  ["3eee5e6fdb0c56b5"] = { "Portami alla ⟦Eastwall Tower=Torre di Levante⟧.", "." },
  ["3ef2600c5fef3d1b"] = { "Ora le loro menti sono corrotte, {race}. Sì, ancora più di prima. Vivono solo per servire e proteggere Razelikh. I frammenti d'amuleto che ognuno di loro custodisce sono la chiave per evocare il signore dei demoni. Quello che non capisci è che nessuno di loro può essere ferito con mezzi convenzionali", "." },
  ["3efc9122fe7b93d0"] = { "{name}! Le nostre provviste si stanno esaurendo e finché non ne arriveranno altre non possiamo lanciare grandi assalti di terra nel ⟦Field of Strife=Pian della Discordia⟧!\n\nParla con il quartiermastro dei Piccatonante. Ti dirà cosa puoi fare per rifornire le nostre forze d'assalto.", "." },
})
